def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find the full separator rows and columns.
    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1 and grid[r][0] != 0]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1 and grid[0][c] != 0]
    sep = grid[sep_rows[0]][0] if sep_rows else (grid[0][sep_cols[0]] if sep_cols else 0)

    row_starts = [0] + [r + 1 for r in sep_rows]
    col_starts = [0] + [c + 1 for c in sep_cols]
    row_ends = sep_rows + [h]
    col_ends = sep_cols + [w]

    # Locate the patterned tile by its larger-than-seed number of nonzero cells.
    pattern = None
    for ri, (r0, r1) in enumerate(zip(row_starts, row_ends)):
        for ci, (c0, c1) in enumerate(zip(col_starts, col_ends)):
            cells = [(r - r0, c - c0) for r in range(r0, r1)
                     for c in range(c0, c1) if grid[r][c] != 0]
            if len(cells) > 4:
                pattern = cells
                break
        if pattern is not None:
            break

    if pattern is None:
        return grid

    out = [row[:] for row in grid]
    for ri, (r0, r1) in enumerate(zip(row_starts, row_ends)):
        c0, c1 = col_starts[0], col_ends[0]
        seed = next((grid[r][c] for r in range(r0, r1) for c in range(c0, c1)
                     if grid[r][c] not in (0, sep)), 0)
        if not seed:
            continue
        for ci, (tc0, tc1) in enumerate(zip(col_starts, col_ends)):
            for r in range(r0, r1):
                for c in range(tc0, tc1):
                    out[r][c] = 0
            for dr, dc in pattern:
                if r0 + dr < r1 and tc0 + dc < tc1:
                    out[r0 + dr][tc0 + dc] = seed

    return out
